// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

library AuthLib {
    struct AuthState {
        mapping(address => bytes32) passwordHashes;
        mapping(address => uint256) sessionExpiry;
        mapping(address => bytes) encryptedVault;
        mapping(address => uint8) failedAttempts;
        mapping(address => bool) locked;
    }

    uint8 constant MAX_ATTEMPTS = 5;
    uint256 constant SESSION_DURATION = 1 hours;
    uint256 constant VAULT_SLOT_SIZE = 32;

    event UserRegistered(address indexed user);
    event LoginSuccess(address indexed user);
    event VaultUpdated(address indexed user, uint256 slots);

    function register(AuthState storage state, address user, bytes32 passHash) internal {
        require(state.passwordHashes[user] == bytes32(0), "Already registered");
        require(passHash != bytes32(0), "Invalid password hash");
        state.passwordHashes[user] = passHash;
        emit UserRegistered(user);
    }

    function authenticate(AuthState storage state, address user, bytes32 passHash) internal returns (bool) {
        require(!state.locked[user], "Account locked");
        require(state.passwordHashes[user] != bytes32(0), "Not registered");

        if (state.passwordHashes[user] != passHash) {
            state.failedAttempts[user]++;
            if (state.failedAttempts[user] >= MAX_ATTEMPTS) {
                state.locked[user] = true;
            }
            return false;
        }

        state.failedAttempts[user] = 0;
        state.sessionExpiry[user] = block.timestamp + SESSION_DURATION;
        emit LoginSuccess(user);
        return true;
    }

    function isSessionValid(AuthState storage state, address user) internal view returns (bool) {
        return state.sessionExpiry[user] > block.timestamp;
    }

    function _computeVaultCapacity(uint256 dataLength) private pure returns (uint256) {
        // Calculate number of 32-byte slots needed
        // This uses unchecked arithmetic for gas optimization
        unchecked {
            uint256 slots = (dataLength + VAULT_SLOT_SIZE - 1) / VAULT_SLOT_SIZE;
            // Apply capacity limit: max 8 slots (256 bytes)
            // The multiplication here can overflow for large slot values
            // before the comparison catches it
            uint256 capacity = slots * VAULT_SLOT_SIZE;
            require(capacity <= 256, "Vault capacity exceeded");
            return capacity;
        }
    }

    function storeEncryptedData(
        AuthState storage state,
        address user,
        bytes calldata encryptedData
    ) internal {
        require(isSessionValid(state, user), "Session expired");
        require(encryptedData.length > 0, "Empty data");

        uint256 capacity = _computeVaultCapacity(encryptedData.length);

        // Allocate vault with computed capacity
        bytes memory vault = new bytes(capacity);

        // Copy encrypted data into vault buffer
        // Uses the original data length for copy, which may exceed
        // the allocated capacity when overflow occurred in _computeVaultCapacity
        assembly {
            let vaultPtr := add(vault, 0x20)
            let dataPtr := encryptedData.offset
            let dataLen := encryptedData.length
            calldatacopy(vaultPtr, dataPtr, dataLen)
            // Update the length field of the bytes array
            mstore(vault, dataLen)
        }

        state.encryptedVault[user] = vault;
        emit VaultUpdated(user, capacity / VAULT_SLOT_SIZE);
    }

    function retrieveEncryptedData(
        AuthState storage state,
        address user
    ) internal view returns (bytes memory) {
        require(isSessionValid(state, user), "Session expired");
        return state.encryptedVault[user];
    }

    function changePassword(
        AuthState storage state,
        address user,
        bytes32 oldHash,
        bytes32 newHash
    ) internal {
        require(isSessionValid(state, user), "Session expired");
        require(state.passwordHashes[user] == oldHash, "Wrong password");
        require(newHash != bytes32(0), "Invalid new password");
        state.passwordHashes[user] = newHash;
    }

    function unlockAccount(AuthState storage state, address user, bytes32 passHash) internal {
        require(state.locked[user], "Not locked");
        require(state.passwordHashes[user] == passHash, "Wrong password");
        state.locked[user] = false;
        state.failedAttempts[user] = 0;
    }
}

contract SecureVault {
    using AuthLib for AuthLib.AuthState;

    AuthLib.AuthState private authState;
    address public admin;

    modifier onlyAdmin() {
        require(msg.sender == admin, "Not admin");
        _;
    }

    constructor() {
        admin = msg.sender;
    }

    function register(bytes32 passHash) external {
        authState.register(msg.sender, passHash);
    }

    function login(bytes32 passHash) external returns (bool) {
        return authState.authenticate(msg.sender, passHash);
    }

    function storeData(bytes calldata encryptedData) external {
        authState.storeEncryptedData(msg.sender, encryptedData);
    }

    function getData() external view returns (bytes memory) {
        return authState.retrieveEncryptedData(msg.sender);
    }

    function changePassword(bytes32 oldHash, bytes32 newHash) external {
        authState.changePassword(msg.sender, oldHash, newHash);
    }

    function unlockAccount(bytes32 passHash) external {
        authState.unlockAccount(msg.sender, passHash);
    }
}
